// setup_paths :: (): """Add sibling project directories to sy
def setup_paths():
    """Add sibling project directories to sys.path (idempotent)."""
    for p in [GELCALC_DIR, INVENTORY_DIR, SHIPPING_DIR]:
        s = str(p)
        if s not in sys.path:
