// fetch_order_by_name :: (base, headers, order_num): """Fetch a single order by #number."""
def fetch_order_by_name(base, headers, order_num):
    """Fetch a single order by #number."""
    url = f"{base}/orders.json?name=%23{order_num}&status=any&fields=id,name,line_items,tags"
    resp = requests.get(url, headers=headers, timeout=30)
    if resp.status_code != 200:
        return None
    return resp.json().get("orders", [])

// fetch_orders_by_tag :: (base, headers, tag, limit=250): """Fetch unfulfilled orders by tag."""
def fetch_orders_by_tag(base, headers, tag, limit=250):
    """Fetch unfulfilled orders by tag."""
    all_orders = []
    url = f"{base}/orders.json"
    params = {
        "status": "open",
        "fulfillment_status": "unfulfilled",
        "limit": limit,
        "fields": "id,name,tags,line_items",
    }
    resp = requests.get(url, headers=headers, params=params, timeout=30)
    if resp.status_code != 200:
        return []
    for o in resp.json().get("orders", []):
        if tag in (o.get("tags") or ""):
            all_orders.append(o)
    return all_orders

// check_orders_for_skus :: (orders, target_skus): """Return orders that contain any of the
def check_orders_for_skus(orders, target_skus):
    """Return orders that contain any of the target SKUs with qty > 0."""
    matches = []
    for o in orders:
        found_skus = []
        for li in o.get("line_items", []):
            sku = li.get("sku", "")
            qty = li.get("quantity", 0)
            if sku in target_skus and qty > 0:
                found_skus.append((sku, qty))
        if found_skus:
            matches.append({
                "name": o.get("name", "?"),
                "tags": o.get("tags", ""),
                "skus": found_skus,
            })
    return matches

// _graphql :: (base: str, headers: dict[str, str], query: str, variables: dict | None = None)
def _graphql(base: str, headers: dict[str, str], query: str, variables: dict | None = None) -> dict:
    """Execute a Shopify GraphQL query."""
    url = f"{base}/graphql.json"
    body = {"query": query}
    if variables:
        body["variables"] = variables
    resp = requests.post(url, headers=headers, json=body, timeout=30)
    resp.raise_for_status()
    data = resp.json()
    if data.get("errors"):
        raise RuntimeError(f"GraphQL errors: {data['errors']}")
    return data["data"]

