// register > apply_zip_routing_tags :: (dry_run: bool = True,)
    async def apply_zip_routing_tags(
        dry_run: bool = True,
    ) -> str:
        """Find unfulfilled Shopify orders in zip-override zones and apply routing tags.

        Reads zip_routing_overrides from GelPackCalculator settings. For each
        unfulfilled order shipping to an override zip:
        1. Checks for conflicting routing tags and removes them
        2. Applies the appropriate routing tag (e.g. !FedEx 2Day - Dallas_AHB!)

        Args:
            dry_run: If True (default), report what would change without modifying orders.
                     Set to False to actually apply tags.

        Returns:
            JSON with tagged orders, conflicts resolved, and any errors.
        """
        try:
            settings = get_inventory_settings()
            store = settings.get("shopify_store_url", "").strip()
            token = settings.get("shopify_access_token", "").strip()
            if not store or not token:
                return to_json({"error": "Shopify credentials not configured"})

            gql_url = f"https://{store}.myshopify.com/admin/api/2024-01/graphql.json"
            rest_base = f"https://{store}.myshopify.com/admin/api/2024-01"
            headers = {"X-Shopify-Access-Token": token, "Content-Type": "application/json"}

            # Load zip overrides from GelPack settings
            gc_path = GELCALC_DIR / "gel_calc_shopify_settings.json"
            if not gc_path.exists():
                return to_json({"error": "GelPack settings not found"})
            with open(gc_path) as f:
                gc = json.load(f)
            overrides = gc.get("zip_routing_overrides", {})
            force_2day_zips = {
                z for z, v in overrides.items() if v.get("action") == "force_2day"
            }
            if not force_2day_zips:
                return to_json({"message": "No force_2day zip overrides configured", "tagged": 0})

            TAG = gc.get("default_routing_tag", "!FedEx 2Day - Dallas_AHB!")
            ROUTING_PREFIXES = ("!ANY", "!NO ", "!FedEx", "!UPS", "!OnTrac")

            # Fetch unfulfilled orders
            cutoff = (datetime.now() - timedelta(days=21)).isoformat()
            url = f"{rest_base}/orders.json"
            params = {
                "status": "open", "fulfillment_status": "unfulfilled",
                "limit": 250, "created_at_min": cutoff,
                "fields": "id,name,tags,shipping_address",
            }
            all_orders = []
            while url:
                resp = requests.get(url, headers=headers, params=params, timeout=60)
                if resp.status_code != 200:
                    return to_json({"error": f"Shopify API returned {resp.status_code}: {resp.text[:200]}"})
                data = resp.json()
                all_orders.extend(data.get("orders", []))
                url = None
                params = None
                link = resp.headers.get("Link", "")
                if 'rel="next"' in link:
                    m = re.search(r'<([^>]+)>;\s*rel="next"', link)
                    if m:
                        url = m.group(1)
                time.sleep(0.3)

            # Find orders needing tags
            targets = []
            for o in all_orders:
                addr = o.get("shipping_address") or {}
                zipcode = (addr.get("zip") or "").strip()
                prefix = zipcode[:3]
                if prefix not in force_2day_zips:
                    continue
                tags = o.get("tags", "") or ""
                tag_list = [t.strip() for t in tags.split(",") if t.strip()]
                routing_tags = [t for t in tag_list if any(t.startswith(p) for p in ROUTING_PREFIXES)]

                already_tagged = TAG in tag_list
                conflicts = [t for t in routing_tags if t != TAG]

                if already_tagged and not conflicts:
                    continue  # already correct

        targets.append({
            "order_id": o["id"],
            "name": o.get("name", ""),
            "city": addr.get("city", ""),
            "state": addr.get("province_code", ""),
            "zip": zipcode,
            "conflicts": conflicts,
            "already_tagged": already_tagged,
        })

    if dry_run:
        return to_json({
            "dry_run": True,
            "orders_to_tag": len(targets),
            "force_2day_zips": sorted(force_2day_zips),
            "tag": TAG,
            "details": targets,
        })

    # Apply tags via GraphQL
    tags_add_q = """
    mutation tagsAdd($id: ID!, $tags: [String!]!) {
      tagsAdd(id: $id, tags: $tags) {
        node { ... on Order { id name } }
        userErrors { field message }
      }
    }
    """
    tags_remove_q = """
    mutation tagsRemove($id: ID!, $tags: [String!]!) {
      tagsRemove(id: $id, tags: $tags) {
        node { ... on Order { id name } }
        userErrors { field message }
      }
    }
    """

    results = {"tagged": 0, "conflicts_resolved": 0, "failed": 0, "details": []}

    for t in targets:
        gid = f"gid://shopify/Order/{t['order_id']}"

        # Remove conflicting routing tags first
        if t["conflicts"]:
            resp = requests.post(gql_url, headers=headers, json={
                "query": tags_remove_q,
                "variables": {"id": gid, "tags": t["conflicts"]},
            }, timeout=30)
            data = resp.json()
            errors = (data.get("data", {}).get("tagsRemove", {})
                      .get("userErrors", []))
            if not errors:
                results["conflicts_resolved"] += 1
            time.sleep(0.3)

        # Add FedEx 2Day tag
        if not t["already_tagged"]:
            resp = requests.post(gql_url, headers=headers, json={
                "query": tags_add_q,
                "variables": {"id": gid, "tags": [TAG]},
            }, timeout=30)
            data = resp.json()
            if "errors" in data:
                results["failed"] += 1
                results["details"].append({
                    "name": t["name"], "error": str(data["errors"])[:100]})
            else:
                ue = (data.get("data", {}).get("tagsAdd", {})
                      .get("userErrors", []))
                if ue:
                    results["failed"] += 1
                    results["details"].append({"name": t["name"], "error": str(ue)})
                else:
                    results["tagged"] += 1
                    results["details"].append({
                        "name": t["name"],
                        "city": t["city"],
                        "zip": t["zip"],
                        "conflicts_removed": t["conflicts"],
                    })
            time.sleep(0.3)

    return to_json(results)
except Exception as e:
    return format_error(e, "apply_zip_routing_tags")

// main :: (): settings
def main():
    settings = _load_settings()
    auth, base_url = _gorgias_auth()
    subdomain = settings.get("gorgias_subdomain", "appyhour")
    creds = settings.get("google_credentials_path", "")
    if not creds or not os.path.exists(creds):
        creds = str(Path(__file__).resolve().parent.parent.parent
                     / "shipping-perfomance-review-accd39ac4b78.json")
    gclient = GoogleIntegration(creds)

    all_rows = gclient.read_sheet(SPREADSHEET_ID, f"'{TAB_NAME}'!A:J")
    print(f"Read {len(all_rows)} rows", flush=True)

    enriched = []
    updates = []
    errors = 0
    processed = 0

    for row_idx, row in enumerate(all_rows):
        if row_idx == 0:
            continue
        while len(row) < 10:
            row.append("")

        order_num = row[2].strip()
        if not order_num:
            continue

        missing = []
        if not row[3].strip(): missing.append("gorgias_link")
        if not row[4].strip(): missing.append("carrier")
        if not row[5].strip(): missing.append("state")
        if not row[6].strip(): missing.append("fc_tag")
        if not row[7].strip(): missing.append("issue_type")
        if not row[8].strip(): missing.append("resolution")
        if not missing:
            continue

        processed += 1
        try:
            shopify_order = _shopify_order_by_name(order_num)
            time.sleep(0.3)

            customer_email = ""
            if shopify_order:
                customer_email = (
                    shopify_order.get("email", "")
                    or shopify_order.get("customer", {}).get("email", "")
                )

            ticket = None
            if any(f in missing for f in ("gorgias_link", "issue_type", "resolution", "state", "fc_tag")):
                ticket = _search_gorgias_by_order(
                    order_num, auth, base_url, customer_email=customer_email,
                )
                time.sleep(0.3)

            new_vals = list(row[:10])
            filled = []

            if not new_vals[3].strip() and ticket:
                new_vals[3] = f"https://{subdomain}.gorgias.com/app/views/238613/{ticket['id']}"
                filled.append("gorgias_link")
            if not new_vals[4].strip() and shopify_order:
                c = _extract_carrier_from_shopify(shopify_order)
                if c:
                    new_vals[4] = c
                    filled.append("carrier")
            if not new_vals[5].strip():
                if shopify_order:
                    s = _extract_state_from_shopify(shopify_order)
                    if s:
                        new_vals[5] = s
                        filled.append("state")
                if not new_vals[5].strip() and ticket:
                    s = _extract_state_from_tags(ticket)
                    if s:
                        new_vals[5] = s
                        filled.append("state")
            if not new_vals[6].strip():
                if shopify_order:
                    fc = _extract_fc_from_shopify_tags(shopify_order)
                    if fc:
                        new_vals[6] = fc
                        filled.append("fc_tag")
                if not new_vals[6].strip() and ticket:
                    fc = _extract_fc_tag(ticket)
                    if fc:
                        new_vals[6] = fc
                        filled.append("fc_tag")
            if not new_vals[7].strip() and ticket:
                cf = ticket.get("custom_fields", {})
                it = cf.get(FIELD_ISSUE_TYPE, {}).get("value", "")
                if it and _matches_valid_prefix(it, VALID_ISSUE_PREFIXES):
                    new_vals[7] = it
                    filled.append("issue_type")
            if not new_vals[8].strip() and ticket:
                cf = ticket.get("custom_fields", {})
                res = cf.get(FIELD_RESOLUTION, {}).get("value", "")
                if res and res not in EXCLUDED_RESOLUTIONS:
                    new_vals[8] = res
                    filled.append("resolution")

            if filled:
                sheet_row = row_idx + 1
                enriched.append({"row": sheet_row, "order": order_num, "filled": filled})
                updates.append({
                    "range": f"'{TAB_NAME}'!A{sheet_row}:J{sheet_row}",
                    "values": [new_vals],
                })

        except Exception as e:
            errors += 1
            print(f"  Error row {row_idx+1} ({order_num}): {e}", flush=True)
            if errors >= 20:
                print("Too many errors, stopping", flush=True)
                break
            time.sleep(2)

        if processed % 25 == 0:
            print(f"  {processed} processed, {len(enriched)} enriched, {errors} errors", flush=True)

    print(f"\nDone: {processed} processed, {len(enriched)} enriched, {errors} errors", flush=True)

    if updates:
        sheets_svc = gclient._sheets
        for i in range(0, len(updates), 100):
            batch = updates[i:i+100]
            sheets_svc.spreadsheets().values().batchUpdate(
                spreadsheetId=SPREADSHEET_ID,
                body={"valueInputOption": "USER_ENTERED", "data": batch},
            ).execute()
            print(f"  Written batch {i//100+1} ({len(batch)} rows)", flush=True)

    for e in enriched[:10]:
        print(f"  Row {e['row']}: {e['order']} -> {e['filled']}")
    if len(enriched) > 10:
        print(f"  ... +{len(enriched)-10} more")
    print("COMPLETE", flush=True)

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc()
        sys.exit(1)

// col_letter :: (n): result
def col_letter(n):
    result = ""
    while True:
        result = chr(65 + n % 26) + result
        n = n // 26 - 1
        if n < 0:
            break
    return result

// fcs_for_week :: (week): """Return the FC list for a given week s
def fcs_for_week(week):
    """Return the FC list for a given week start date."""
    d = week.date() if isinstance(week, datetime) else week
    if d >= COG_RETIRED:
        return ERA_FEB
    if d >= GRIPCA_RETIRED:
        return ERA_JAN
    return ERA_ALL

