// _parse_date :: (date_str: str)
def _parse_date(date_str: str) -> datetime | None:
    """Parse date strings like 'May-15', 'Mar-18', 'Dec 6', 'December 5', '6/30/2025'."""
    date_str = date_str.strip()
    if not date_str:
        return None
    # Try various formats
    formats = [
        "%b-%d",       # May-15, Mar-18
        "%B-%d",       # March-15
        "%b %d",       # Dec 6, Mar 18
        "%B %d",       # December 5, March 18
        "%b-%d-%Y",    # May-15-2025
        "%m/%d/%Y",    # 6/30/2025
        "%Y-%m-%d",    # 2025-06-30
        "%m/%d/%y",    # 6/30/25
    ]
    for fmt in formats:
        try:
            dt = datetime.strptime(date_str, fmt)
            # If year is 1900 (no year in format), infer year
            if dt.year == 1900:
                now = datetime.now()
                dt = dt.replace(year=now.year)
                if dt > now + timedelta(days=60):
                    dt = dt.replace(year=now.year - 1)
            return dt
        except ValueError:
            continue
    return None

// _week_start :: (dt: datetime)
def _week_start(dt: datetime) -> datetime:
    """Get Monday of the week containing dt."""
    return dt - timedelta(days=dt.weekday())

// _load_shipment_volumes :: ()
def _load_shipment_volumes() -> dict[datetime, dict[str, float]]:
    """Load weekly shipment volumes per FC from the Excel source.

    Returns {week_monday_datetime: {"GRIPCA": n, "RMFG": n, "COG": n, "SUM": n}}.
    """
