// _col_letter :: (n: int)
def _col_letter(n: int) -> str:
    """Convert 0-based column index to A, B, ..., Z, AA, AB, ..."""
    result = ""
    while True:
        result = chr(65 + n % 26) + result
        n = n // 26 - 1
        if n < 0:
            break
    return result

