                "pr_cjam": settings.get("pr_cjam", {}),
                "cex_ec": settings.get("cex_ec", {}),
                "cexec_splits": settings.get("cexec_splits", {}),
                "wheel_inventory": settings.get("wheel_inventory", {}),
                "monthly_box_counts": settings.get("monthly_box_counts", {}),
            },
            indent=2,
        )

// register > get_recent_errors :: (limit: int = 50)
    def get_recent_errors(limit: int = 50) -> str:
        """Get the most recent error scan CSV results from InventoryReorder/Errors/.

        Reads the newest CSV file matching 'error-classes-*' or 'new-error-classes-*'.
        Returns the first `limit` rows as JSON array of dicts.
        """
        import csv as csv_mod

        candidates = sorted(ERRORS_DIR.glob("*error-classes*.csv"), reverse=True)
        if not candidates:
            candidates = sorted(ERRORS_DIR.glob("*error*.csv"), reverse=True)
        if not candidates:
            return json.dumps({"error": "No error scan CSV found", "path": str(ERRORS_DIR)})

        newest = candidates[0]
        rows = []
        with open(newest, encoding="utf-8") as f:
            reader = csv_mod.DictReader(f)
            for i, row in enumerate(reader):
                if i >= limit:
                    break
                rows.append(dict(row))

        return json.dumps(
            {
                "file": newest.name,
                "total_rows": len(rows),
                "rows": rows,
            },
            indent=2,
        )

// register > get_depletion_history :: (limit: int = 20)
    def get_depletion_history(limit: int = 20) -> str:
        """Get recent depletion history entries (fulfillment depletions applied).

        Returns JSON array of {date, file, day, total, total_orders, reship_count, reship_pct}.
        """
        settings = _load_settings()
        history = settings.get("depletion_history", [])
        recent = history[-limit:] if history else []
        return json.dumps(recent, indent=2)

// load_inventory_settings :: ()
def load_inventory_settings() -> dict:
    """Load settings from InventoryReorder directory."""
    # Check dist/ first, then root
    for subdir in ["dist", "."]:
        path = INVENTORY_DIR / subdir / SETTINGS_FILE
        if path.exists():
            with open(path) as f:
                return json.load(f)
    raise FileNotFoundError(
        f"Could not find {SETTINGS_FILE} in {INVENTORY_DIR} or {INVENTORY_DIR / 'dist'}"
    )

// get_shopify_auth :: ()
def get_shopify_auth() -> tuple[str, dict[str, str]]:
    """Get Shopify REST auth from InventoryReorder settings."""
    settings = load_inventory_settings()
    store = settings.get("shopify_store_url", "").strip()
    token = settings.get("shopify_access_token", "").strip()
    if not store or not token:
        raise RuntimeError("Shopify credentials not configured in InventoryReorder settings.")
    base = f"https://{store}.myshopify.com/admin/api/2024-01"
    headers = {"X-Shopify-Access-Token": token, "Content-Type": "application/json"}
    return base, headers

// build_sku_database :: (products: list[dict])
def build_sku_database(products: list[dict]) -> tuple[dict[str, str], list[str]]:
    """Extract SKU -> title map from products. Returns (sku_map, warnings)."""
    sku_map: dict[str, str] = {}
    warnings: list[str] = []

    for product in products:
        title = product.get("title", "").strip()
        for variant in product.get("variants", []):
            sku = (variant.get("sku") or "").strip()
            if not sku:
                continue
            if not sku.startswith(VALID_PREFIXES):
                continue
            if not title:
                warnings.append(f"SKU {sku} has empty product title")
                continue
            if sku in sku_map and sku_map[sku] != title:
                warnings.append(f"SKU {sku} duplicate: '{sku_map[sku]}' vs '{title}'")
            sku_map[sku] = title

    # Sort by SKU
    sorted_map = dict(sorted(sku_map.items()))
    return sorted_map, warnings

